blocks.patch:
diff --git a/mm/swap_state.c b/mm/swap_state.c
index c226fe726..ddc8c45ce 100644
--- a/mm/swap_state.c
+++ b/mm/swap_state.c
@@ -51,6 +51,15 @@ static bool enable_vma_readahead __read_mostly = true;

 #define SWAP_RA_ORDER_CEILING	5

+/*
+ * A fault that opens an xswap readahead window waits for the whole window:
+ * the target is plugged and usually merged with its backend neighbours into
+ * one read.  In a sequential stream that fault is the only miss of its
+ * window, so the window size sets the stream's tail latency.  Cap it at
+ * 4 pages, in cluster and VMA mode, below page_cluster's default of 8.
+ */
+#define XSWAP_RA_ORDER		2
+
 #define SWAP_RA_WIN_SHIFT	(PAGE_SHIFT / 2)
 #define SWAP_RA_HITS_MASK	((1UL << SWAP_RA_WIN_SHIFT) - 1)
 #define SWAP_RA_HITS_MAX	SWAP_RA_HITS_MASK
@@ -1095,6 +1104,8 @@ struct folio *swap_cluster_readahead(swp_entry_t entry, gfp_t gfp_mask,
 		goto skip;

 	mask = swapin_nr_pages(offset) - 1;
+	if (si->flags & SWP_XSWAP)
+		mask = min(mask, (1UL << XSWAP_RA_ORDER) - 1);
 	if (!mask)
 		goto skip;

@@ -1126,14 +1137,17 @@ struct folio *swap_cluster_readahead(swp_entry_t entry, gfp_t gfp_mask,
 }

 static int swap_vma_ra_win(struct vm_fault *vmf, unsigned long *start,
-			   unsigned long *end)
+			   unsigned long *end, bool xswap)
 {
 	struct vm_area_struct *vma = vmf->vma;
 	unsigned long ra_val;
 	unsigned long faddr, prev_faddr, left, right;
 	unsigned int max_win, hits, prev_win, win;
+	int order = min(READ_ONCE(page_cluster), SWAP_RA_ORDER_CEILING);

-	max_win = 1 << min(READ_ONCE(page_cluster), SWAP_RA_ORDER_CEILING);
+	if (xswap)
+		order = min(order, XSWAP_RA_ORDER);
+	max_win = 1 << order;
 	if (max_win == 1)
 		return 1;

@@ -1200,7 +1214,7 @@ static struct folio *swap_vma_readahead(swp_entry_t targ_entry, gfp_t gfp_mask,
 	    !xswap_readahead_wanted(tsi, targ_entry))
 		goto skip;

-	win = swap_vma_ra_win(vmf, &start, &end);
+	win = swap_vma_ra_win(vmf, &start, &end, tsi->flags & SWP_XSWAP);
 	if (win == 1)
 		goto skip;
